out_topics = []
missing = []
for t in auth["topics"]:
    tid = t["topic_id"]
    cp = []
    for c in t.get("concepts", []):
        cid = c["concept_id"]
        for i, blk in enumerate(c["content"]):
            if blk.get("type") != "paragraph":
                continue
            key = (cid, i)
            if key not in CONCEPT_PUB:
                missing.append(key)
                continue
            cp.append({"concept_id": cid, "content_index": i,
                       "publication_text": CONCEPT_PUB[key]})
    out_topics.append({
        "topic_id": tid,
        "publication_text": PUB_TEXT[tid],
        "publication_chunk": chunks[tid] + "\n\n" + CHUNK_PROSE[tid],
        "concept_publication": cp,
    })

assert not missing, missing
assert [t["topic_id"] for t in out_topics] == [t["topic_id"] for t in auth["topics"]]

# hard checks
import re
DEVA = re.compile(r"[ऀ-ॿ]")
LATIN = re.compile(r"[A-Za-z]")
for t in out_topics:
    for fld in ("publication_text", "publication_chunk"):
        s = t[fld]
        assert "।" not in s, ("danda", t["topic_id"], fld)
        assert not DEVA.search(s), ("devanagari", t["topic_id"], fld)
        assert not LATIN.search(s), ("latin", t["topic_id"], fld)
    assert t["publication_chunk"].startswith(chunks[t["topic_id"]])
    for e in t["concept_publication"]:
        s = e["publication_text"]
        assert "।" not in s and not DEVA.search(s) and not LATIN.search(s), e["concept_id"]

payload = {"topics": out_topics}
p = os.path.join(BASE, "16_publication.json")
with io.open(p, "w", encoding="utf-8") as f:
    json.dump(payload, f, ensure_ascii=False, indent=2)
    f.write("\n")

print("written", p)
for t in out_topics:
    print(t["topic_id"], "expl_words", len(t["publication_text"].split()),
          "chunk_words", len(t["publication_chunk"].split()),
          "concept_paras", len(t["concept_publication"]))
